  private final val indentationPadding = "   |   |   |   |   |   |   |   |   |   |"

  protected def pSub(x: Type, y: Type)(implicit negate: Boolean, history: Set[hType]): CFormula = {
     val savedDepthForPrinting = pSubDepthForPrinting
     val indentation = indentationPadding.take(savedDepthForPrinting % indentationPadding.size)
     if (debugSubtype) {
//         System.err.println(indentation + "psub > (" + x.getClass + "!" + x + ", " + y.getClass + "!" + y + ", " + negate + "), history=" + history)
//         System.err.println(indentation + "psub > (" + x.getClass + "!" + x + ", " + y.getClass + "!" + y + ", " + negate + "), env=" + env)
         System.err.println(indentation + "psub > (" + x + ", " + y + ", " + negate + "), env=" + env)
         pSubDepthForPrinting += 1
	 if (pSubDepthForPrinting > 50) bug(x, "pSub stack getting too big!")
     }
     val rval = if (x == y)
           pTrue()
         else if (cacheSubtypes && !opensSizes(x))
           traits.groundAnswer(true, x, y, negate) match {
            case null => pSubMemo.get((x, y, negate, history)) match {
              case Some(v) => traits.readContext(); v
              case _ =>
                val before = traits.contextReads
                val result = pSubInner(x,y)
                pSubMemo += ((x, y, negate, history) -> result)
                traits.ground(true, x, y, negate, before, result)
                result
            }
            case v => v
           }
         else pSubInner(x,y)
     if (debugSubtype) {
         System.err.println(indentation + "psub < (" + x + ", " + y + ", " + negate + ") RETURNS " + rval)
         pSubDepthForPrinting = savedDepthForPrinting
     }
     rval

  /**
   * The bindings that the where clause's trait constraints give: each type
   * variable X named by a constraint X extends B, bound in the declared
   * bindings or outside them, rebound with B added to its bounds.
   */
  def constraintBounds(outer: KindEnv, declared: Iterable[KindBinding],
                       where: Option[WhereClause]): Iterable[KindBinding] = where match {
    case Some(SWhereClause(_, _, constraints)) =>
      val scope = new NestedKindEnv(outer, declared)
      val byName = constraints.collect { case SWhereExtends(_, name, supers) => (name, supers) }
      val names = byName.map(_._1).foldLeft(List[Id]())((acc, n) =>
        if (acc.exists(_.getText == n.getText)) acc else acc :+ n)
      names.flatMap(n => scope.lookup(n) match {
        case Some(KindBinding(bn, sp)) if sp.getKind.isInstanceOf[KindType] =>
          val extra = byName.filter(_._1.getText == n.getText).flatMap(_._2)
          val supers = toListFromImmutable(sp.getExtendsClause) ++ extra
          List(KindBinding(bn, NF.makeStaticParam(sp, sp.getName.asInstanceOf[Id], toJavaList(supers))))
        case _ => Nil
      })
    case _ => Nil
  }

